"""Extract a compact source-bound causal index without changing the raw capture."""
from pathlib import Path
import argparse,json,hashlib,collections
parser=argparse.ArgumentParser();parser.add_argument('report',type=Path);parser.add_argument('out',type=Path);args=parser.parse_args();r=json.loads(args.report.read_bytes());assert r['complete']and r['browserClosed']and r['sourceFilesVerifiedAfterRun'];o=r['observation'];contacts=o['contacts'];impacts=o['impacts'];steps=o['vehicleSteps'];samples=o['samples'];pairs=collections.Counter()
for c in contacts:pairs[(c.get('collider')or{}).get('type'),(c.get('collider')or{}).get('id'),c.get('staticShape')]+=1
contactgroups=[]
for (kind,id,shape),count in pairs.items():
 rows=[c for c in contacts if((c.get('collider')or{}).get('type'),(c.get('collider')or{}).get('id'),c.get('staticShape'))==(kind,id,shape)];contactgroups.append({'type':kind,'id':id,'staticShapeIndex':shape,'count':count,'firstT':rows[0]['t'],'lastT':rows[-1]['t']})
