blockstep=min(v87,key=lambda s:abs(s['t']-block['t']))if block and v87 else None
pedgaps=[s for s in o['pedGapCalls']if isinstance(s.get('result'),(int,float))];cross=o['crossingCalls'];first=contacts[0]if contacts else None
out={'sourceCommit':r['sourceCommit'],'rawReport':str(args.report),'rawBytes':args.report.stat().st_size,'rawSha256':hashlib.sha256(args.report.read_bytes()).hexdigest(),'producerSha256':r['toolSha256'],'complete':True,'browserClosed':True,'sourceFilesVerifiedAfterRun':True,'errors':r['errors'],'consoleErrors':r['consoleErrors'],'httpErrors':r['httpErrors'],'initial':{k:r['initial'].get(k)for k in ['city','district','start','target','routeTotal','vehicles','peds','quality']},'initialAdmission':{k:r['initial'].get('initialAdmission',{}).get(k)for k in ['passed','unresolved','unknownHeights','identityPreserved']},'warm':r['warm'],'drive':r['drive'],'contactGroups':contactgroups,'impactKinds':dict(collections.Counter(i['what']for i in impacts)),'firstContact':first,'firstImpact':impacts[0]if impacts else None,'staticShapes':o['staticShapes'],'vehicle87StoppedSamples':len(stopped),'vehicle87StoredLeaders':dict(leaders),'vehicle87StopReasons':dict(stopReasons),'trafficBlockageIssue':block,'vehicle87AtBlockage':blockstep,'representativeSamples':selected,'pedestrianGapCallsWithFiniteResult':len(pedgaps),'crossingCallsTrue':len(cross),'actualPlacements':o['placements'],'actualTrafficClears':o['clears'],'scope':'Compact index of the unmodified native observer. Other raw samples/impacts/claims/ped callbacks remain in raw JSON. Null in numeric Infinity fields is JSON serialization, not a zero distance.'};args.out.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'drive':r['drive']['result'],'contacts':len(contacts),'contactGroups':contactgroups,'impacts':out['impactKinds'],'v87Stopped':len(stopped),'v87Leaders':dict(leaders),'v87Reasons':dict(stopReasons),'trueCrossingCalls':len(cross),'finitePedGapCalls':len(pedgaps),'placements':len(o['placements'])},indent=2))
